<template><main class="wrap"><el-button text @click="router.push('/orders')">← 注文履歴に戻る</el-button><el-skeleton v-if="loading" :rows="10" animated/><el-result v-else-if="error" icon="error" title="注文を読み込めません" :sub-title="error"/><template v-else><div class="head"><div><h2>注文詳細</h2><p>注文番号：{{order.orderNo}}</p></div><div><el-tag :type="types[order.status]||'info'">{{labels[order.status]||'不明'}}</el-tag><el-button v-if="order.status===0" type="primary" :loading="paying" @click="pay">支払いを完了する</el-button></div></div><el-card><template #header>配送先情報</template><el-descriptions :column="1" border><el-descriptions-item label="受取人">{{order.receiverName}}</el-descriptions-item><el-descriptions-item label="電話番号">{{order.receiverPhone}}</el-descriptions-item><el-descriptions-item label="配送先住所">{{order.shippingAddress}}</el-descriptions-item></el-descriptions></el-card><el-card class="card"><template #header>注文商品</template><el-table :data="order.items||[]"><el-table-column prop="productName" label="商品名"/><el-table-column label="単価"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column label="小計"><template #default="{row}">¥{{money(row.price*row.quantity)}}</template></el-table-column></el-table><p class="total">合計金額：¥{{money(order.totalAmount)}}</p></el-card></template></main></template>
<script setup>import{onMounted,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{useRoute,useRouter}from'vue-router';import{getOrderDetail,payOrder}from'@/api/order';const route=useRoute(),router=useRouter(),order=ref(null),loading=ref(false),paying=ref(false),error=ref(''),labels=['未払い','支払い済み','発送済み','完了','キャンセル'],types=['warning','success','primary','success','info'],money=v=>Number(v).toFixed(2);const load=async()=>{loading.value=true;try{order.value=(await getOrderDetail(route.params.id)).data}catch(e){error.value=e.response?.status===404?'注文が見つかりません。':'時間をおいて再度お試しください。'}finally{loading.value=false}};const pay=async()=>{try{await ElMessageBox.confirm('テスト用の疑似決済を実行しますか？','支払いの確認');paying.value=true;order.value=(await payOrder(order.value.id)).data;ElMessage.success('支払いが完了しました')}catch(e){if(e!=='cancel')ElMessage.error(e.response?.data?.message||'支払いに失敗しました')}finally{paying.value=false}};watch(()=>route.params.id,load);onMounted(load)</script><style scoped>.wrap{max-width:1080px;margin:auto;padding:24px}.head{display:flex;justify-content:space-between;align-items:center;margin:16px 0}.card{margin-top:20px}.total{text-align:right;color:#f56c6c;font-size:20px;font-weight:700}</style>
